namespace QrCodeGenerator.Core.Simbologias;

/// <summary>
/// A tabela de Application Identifiers do GS1. Gerado por
/// <c>`spec/gerar-tabelas-gs1.py` a partir do JSON-LD de ref.gs1.org.</c>
/// </summary>
/// <remarks><para>Sao 541 AIs e nao estao escritos a mao de proposito: mais de
/// quinhentos AIs nao se escrevem de memoria, e um AI com o comprimento errado
/// da um codigo que se desenha certo e que o leitor le como invalido.</para>
/// <para>A origem e' https://ref.gs1.org/ai/?lang=en.</para></remarks>
public static class TabelasGs1
{
    /// <summary>Um componente de um AI: o tipo, e o comprimento fixo ou maximo.</summary>
    /// <remarks><para><b>Um dos dois e' sempre nulo</b>, e e' assim que se
    /// distingue um campo de comprimento fixo de um variavel sem um booleano a
    /// mais. <b>Um campo que aceite os dois nao se sabe ler</b>: o AI <c>3103</c>
    /// e' um campo fixo de tres digitos mais um variavel, e nao um campo fixo de
    /// quatro.</para></remarks>
    public sealed record Componente(string Tipo, int? Fixo, int? Maximo);

    /// <summary>Um AI, com tudo o que o encoder precisa dele.</summary>
    /// <remarks><para><c>Separador</c> diz se o campo precisa de um FNC1 a
    /// separa-lo do seguinte. <b>E' a razao de existir esta tabela</b>: sem ela
    /// nao se sabe onde acaba <c>(10)LOTE-A1</c> e onde comeca o campo
    /// seguinte.</para>
    /// <para><c>Resto</c> so' existe na procura: um AI procurado directamente
    /// tem <c>Resto</c> nulo, e e' por isso que nao ha um campo separado para o
    /// numero procurado.</para></remarks>
    public sealed record Ai(
        string Numero,
        string Formato,
        int? Fixo,
        int? Maximo,
        IReadOnlyList<Componente> Campos,
        bool Separador,
        string Regex,
        string? Resto)
    {
        /// <summary>O mesmo AI, com o numero procurado e o que sobrou.</summary>
        public Ai Buscado(string numeroEfectivo, string? restoEfectivo) =>
            new(numeroEfectivo, Formato, Fixo, Maximo, Campos, Separador, Regex,
                restoEfectivo);
    }

